import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side','price','qty','alive'}
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    counter = 0

    def clean(heap):
        while heap:
            key, arr, oid = heap[0]
            o = book.get(oid)
            if o is None or not o['alive'] or o['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['alive'] and o['qty'] > 0:
                o['alive'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival = counter
        counter += 1
        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            clean(opp_heap)
            if not opp_heap:
                break
            key, arr, oid2 = opp_heap[0]
            if side == 'buy':
                opp_price = key
            else:
                opp_price = -key

            if typ != 'market':
                if side == 'buy' and price < opp_price:
                    break
                if side == 'sell' and price > opp_price:
                    break

            o2 = book[oid2]
            trade_qty = min(remaining, o2['qty'])
            trade_price = o2['price']

            if side == 'buy':
                trades.append([oid, oid2, trade_price, trade_qty])
            else:
                trades.append([oid2, oid, trade_price, trade_qty])

            remaining -= trade_qty
            o2['qty'] -= trade_qty

            if o2['qty'] == 0:
                o2['alive'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'alive': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        else:
            if typ == 'limit':
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'alive': False}
            else:
                # ioc/market - store as inactive record (no resting), qty 0
                p = price if price is not None else 0
                book[oid] = {'side': side, 'price': p, 'qty': 0, 'alive': False}

    return trades

